from skill_extraction import add_skills_list

# ── Page config ────────────────────────────────────────────────────────────
st.set_page_config(
    page_title="Indian Job Market Intelligence",
    page_icon="🇮🇳",
    layout="wide",
    initial_sidebar_state="expanded",
)

# ── Global CSS ─────────────────────────────────────────────────────────────
st.markdown(
    """
    <style>
    /* ── Base ── */
    html, body, [class*="css"] { font-family: -apple-system,"Segoe UI",system-ui,sans-serif; }

    /* ── Sidebar ── */
    [data-testid="stSidebar"] {
        background: #f7f8fa;
        border-right: 1px solid #e5e7eb;
    }
    [data-testid="stSidebar"] .block-container { padding-top: 1.5rem; }

    /* ── KPI Cards ── */
    .kpi-card {
        background: #ffffff;
        border: 1px solid #e5e7eb;
        border-radius: 10px;
        padding: 1.1rem 1.4rem;
        text-align: center;
    }
    .kpi-label { font-size: 0.78rem; color: #57606a; letter-spacing: 0.04em; text-transform: uppercase; margin-bottom: 4px; }
    .kpi-value { font-size: 1.9rem; font-weight: 700; color: #1f2328; line-height: 1.15; }
    .kpi-sub   { font-size: 0.75rem; color: #57606a; margin-top: 3px; }

    /* ── Section headers ── */
    .section-header {
        font-size: 1.05rem;
        font-weight: 600;
        color: #1f2328;
        padding-bottom: 6px;
        border-bottom: 2px solid #3b82d4;
        margin-bottom: 1rem;
    }

    /* ── Page title ── */
    .page-title {
        font-size: 1.65rem;
        font-weight: 700;
        color: #1f2328;
        margin-bottom: 0.2rem;
    }
    .page-subtitle {
        font-size: 0.9rem;
        color: #57606a;
        margin-bottom: 1.4rem;
    }

    /* ── Divider ── */
    hr.light { border: none; border-top: 1px solid #e5e7eb; margin: 1rem 0; }

    /* ── Hide default Streamlit header ── */
    #MainMenu, footer, header { visibility: hidden; }

    /* ── Chart container card ── */
    .chart-card {
        background: #ffffff;
        border: 1px solid #e5e7eb;
        border-radius: 10px;
        padding: 1rem;
        margin-bottom: 1rem;
    }
    </style>
    """,
    unsafe_allow_html=True,
)

# ── Sidebar header ─────────────────────────────────────────────────────────
with st.sidebar:
    st.markdown(
        """
        <div style="text-align:center;padding:0.5rem 0 1rem 0;">
            <span style="font-size:2rem;">🇮🇳</span>
            <div style="font-size:1rem;font-weight:700;color:#1f2328;margin-top:4px;">
                Indian Job Market
            </div>
            <div style="font-size:0.75rem;color:#57606a;">Intelligence Dashboard · 2025</div>
        </div>
        """,
        unsafe_allow_html=True,
    )
    st.divider()

    # Dataset path override
    data_path = st.text_input(
        "Dataset path",
        value=DEFAULT_DATA_PATH,
        help="Absolute or relative path to indian_job_market.csv",
    )
    st.caption("97K+ job postings · Naukri.com · 2025")

# ── Load & cache dataset ───────────────────────────────────────────────────
@st.cache_data(show_spinner=False)
def get_clean_data(path: str) -> "pd.DataFrame":
    raw = load_raw_data(path)
    cleaned = clean_data(raw)
    featured = engineer_features(cleaned)
    featured = add_skills_list(featured)
    return featured


with st.spinner("Loading & cleaning dataset…"):
    try:
        df = get_clean_data(data_path)
        st.session_state["df"] = df
    except FileNotFoundError as e:
        st.error(str(e))
        st.stop()
    except Exception as e:
        st.error(f"Unexpected error loading data: {e}")
        st.stop()

# ── Home / landing ─────────────────────────────────────────────────────────
st.markdown(
    """
    <div class="page-title">🇮🇳 Indian Job Market Intelligence</div>
    <div class="page-subtitle">
        Interactive analytics dashboard for the Indian Job Market 2025 dataset — 
        built as a Data Analyst portfolio project.
    </div>
    """,
    unsafe_allow_html=True,
)

# Dataset status banner
raw_info = get_dataset_info(load_raw_data(data_path))
c1, c2, c3, c4 = st.columns(4)
for col, label, val in zip(
    [c1, c2, c3, c4],
    ["Raw Rows", "After Cleaning", "Columns", "Duplicates Removed"],
    [
        f"{raw_info['rows']:,}",
        f"{len(df):,}",
        str(raw_info["columns"]),
        f"{raw_info['duplicates']:,}",
    ],
):
    col.markdown(
        f"""<div class="kpi-card">
              <div class="kpi-label">{label}</div>
              <div class="kpi-value">{val}</div>
            </div>""",
        unsafe_allow_html=True,
    )

st.markdown("<hr class='light'>", unsafe_allow_html=True)

st.info(
    "👈  Use the **sidebar** to navigate between pages: "
    "Overview · Job Demand · Skill Intelligence · Salary · Experience · Fresher Jobs · Company & Location",
    icon="ℹ️",
)

# Navigation cards
cols = st.columns(4)
pages = [
    ("📊", "Job Market Overview", "Total jobs, top roles, top companies & timeline"),
    ("🔍", "Job Demand Analysis", "Most demanded roles, locations & experience levels"),
    ("🛠️", "Skill Intelligence", "Top skills, skill gaps & co-occurrence analysis"),
    ("💰", "Salary Intelligence", "Salary distributions, by role, location & skill"),
    ("📈", "Experience Analysis", "Jobs by seniority, salary vs experience"),
    ("🎓", "Fresher Opportunities", "Entry-level jobs, fresher-friendly companies"),
    ("🏢", "Company & Location", "Top employers, cities & company ratings"),
]
for i, (icon, title, desc) in enumerate(pages):
    cols[i % 4].markdown(
        f"""<div class="kpi-card" style="text-align:left;margin-bottom:0.6rem;">
              <div style="font-size:1.4rem;">{icon}</div>
              <div style="font-weight:600;font-size:0.9rem;color:#1f2328;margin:4px 0 2px 0;">{title}</div>
              <div style="font-size:0.75rem;color:#57606a;">{desc}</div>
            </div>""",
        unsafe_allow_html=True,
    )

st.markdown(
    "<div style='text-align:center;color:#57606a;font-size:0.75rem;margin-top:2rem;"
    "border-top:1px solid #e5e7eb;padding-top:0.8rem;'>"
    "Data Source: Naukri.com · Dataset: Indian Job Market 2025 · Built with Streamlit &amp; Plotly"
    "</div>",
