st.markdown("<hr class='light'>", unsafe_allow_html=True)

st.info(
    "👈  Use the **sidebar** to navigate between all **13 pages** of this dashboard.",
    icon="ℹ️",
)

# Navigation cards
cols = st.columns(4)
pages = [
    ("📊", "Job Market Overview",       "Total jobs, top roles, top companies & timeline"),
    ("🔍", "Job Demand Analysis",        "Most demanded roles, locations & experience levels"),
    ("🛠️", "Skill Intelligence",         "Top skills, skill gaps & co-occurrence analysis"),
    ("💰", "Salary Intelligence",        "Salary distributions, by role, location & skill"),
    ("📈", "Experience Analysis",        "Jobs by seniority, salary vs experience"),
    ("🌱", "Fresher Opportunities",      "Entry-level jobs, fresher-friendly companies"),
    ("🏢", "Company & Location",         "Top employers, cities & company ratings"),
    ("🔎", "Job Explorer",               "Search & filter 97K+ postings interactively"),
    ("🗄️", "SQL Analytics",              "12 analytical SQL queries on in-memory SQLite"),
    ("📈", "Statistical Insights",       "Descriptive stats, correlations & ANOVA"),
    ("🤖", "Salary Prediction",          "ML model to estimate salary for a job profile"),
    ("🎯", "Career Skill Gap Analyzer",  "Compare your skills vs what employers want"),
    ("📁", "Dataset & Data Quality",     "Data cleaning report & quality metrics"),
]
for i, (icon, title, desc) in enumerate(pages):
    cols[i % 4].markdown(
        f"""<div class="kpi-card" style="text-align:left;margin-bottom:0.6rem;">
              <div style="font-size:1.4rem;">{icon}</div>
              <div style="font-weight:600;font-size:0.9rem;color:#1f2328;margin:4px 0 2px 0;">{title}</div>
              <div style="font-size:0.75rem;color:#57606a;">{desc}</div>
            </div>""",
        unsafe_allow_html=True,
    )

st.markdown(
    "<div style='text-align:center;color:#57606a;font-size:0.75rem;margin-top:2rem;"
    "border-top:1px solid #e5e7eb;padding-top:0.8rem;'>"
    "Data Source: Naukri.com · Dataset: Indian Job Market 2025 · Built with Streamlit &amp; Plotly"
    "</div>",
    unsafe_allow_html=True,
)

