"""
ui_helpers.py — Shared Streamlit UI components for the dark-theme dashboard.
"""

import streamlit as st
import plotly.graph_objects as go
import plotly.express as px

# ── Palette ────────────────────────────────────────────────────────────────
PRIMARY        = "#4f8ef7"   # accent blue
SECONDARY      = "#7c5cd8"   # purple
ACCENT         = "#4f8ef7"   # same as primary for compat
ACCENT_GREEN   = "#22c55e"
ACCENT_AMBER   = "#f59e0b"
ACCENT_RED     = "#ef4444"
MUTED          = "#8b92a8"
TEXT           = "#e8eaf0"
BG             = "#0f1117"
SURFACE        = "#1a1f2e"
SURFACE2       = "#242938"
BORDER         = "#2d3348"

QUAL_COLORS = [
    "#4f8ef7", "#22c55e", "#f59e0b", "#ef4444",
    "#7c5cd8", "#06b6d4", "#ec4899", "#10b981",
    "#f97316", "#8b5cf6",
]

# ── CSS ────────────────────────────────────────────────────────────────────

PAGE_CSS = """
<style>
/* ── Base ── */
html, body, [class*="css"] {
    font-family: "Inter", -apple-system, "Segoe UI", system-ui, sans-serif;
    background-color: #0f1117;
    color: #e8eaf0;
}

/* ── Scrollbar ── */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: #0f1117; }
::-webkit-scrollbar-thumb { background: #2d3348; border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: #4f8ef7; }

/* ── Hide default chrome ── */
#MainMenu, footer, header { visibility: hidden; }
[data-testid="stDecoration"] { display: none; }

/* ── App background ── */
.stApp { background-color: #0f1117; }
[data-testid="stAppViewContainer"] { background-color: #0f1117; }
[data-testid="stHeader"] { background-color: #0f1117; }

/* ── Sidebar ── */
[data-testid="stSidebar"] {
    background: #1a1f2e;
    border-right: 1px solid #2d3348;
}
[data-testid="stSidebar"] .stMarkdown p {
    color: #8b92a8;
    font-size: 0.72rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    padding: 0.6rem 0 0.2rem 0;
    margin: 0;
}
[data-testid="stSidebar"] [data-testid="stSelectbox"] label,
[data-testid="stSidebar"] [data-testid="stMultiSelect"] label {
    color: #8b92a8 !important;
    font-size: 0.8rem;
}

/* Sidebar nav items */
[data-testid="stSidebarNav"] a {
    color: #8b92a8 !important;
    border-radius: 6px;
    padding: 4px 8px;
    font-size: 0.85rem;
}
[data-testid="stSidebarNav"] a:hover,
[data-testid="stSidebarNav"] a[aria-current="page"] {
    background: #242938 !important;
    color: #e8eaf0 !important;
}

/* ── Main content ── */
.block-container {
    padding-top: 1.8rem;
    padding-bottom: 2rem;
    max-width: 1200px;
}

/* ── Page title / subtitle ── */
.page-title {
    font-size: 1.7rem;
    font-weight: 700;
    color: #e8eaf0;
    margin-bottom: 0.2rem;
    line-height: 1.2;
}
.page-subtitle {
    font-size: 0.9rem;
    color: #8b92a8;
    margin-bottom: 1.6rem;
}

/* ── Section headers ── */
.section-header {
    font-size: 0.95rem;
    font-weight: 600;
    color: #e8eaf0;
    padding: 0.5rem 0 0.5rem 0.8rem;
    border-left: 3px solid #4f8ef7;
    margin: 1.4rem 0 0.9rem 0;
    background: rgba(79, 142, 247, 0.05);
    border-radius: 0 4px 4px 0;
}

/* ── KPI cards ── */
.kpi-card {
    background: #1a1f2e;
    border: 1px solid #2d3348;
    border-radius: 10px;
    padding: 1.1rem 1.2rem;
    text-align: center;
    transition: border-color 0.2s;
}
.kpi-card:hover { border-color: #4f8ef7; }
.kpi-label {
    font-size: 0.72rem;
    color: #8b92a8;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    margin-bottom: 6px;
}
.kpi-value {
    font-size: 1.9rem;
    font-weight: 700;
    color: #e8eaf0;
    line-height: 1.1;
}
.kpi-sub {
    font-size: 0.72rem;
    color: #8b92a8;
    margin-top: 4px;
}

/* ── Insight card ── */
.insight-card {
    background: rgba(34, 197, 94, 0.07);
    border: 1px solid rgba(34, 197, 94, 0.35);
    border-radius: 8px;
    padding: 0.85rem 1rem;
    color: #e8eaf0;
    font-size: 0.88rem;
    line-height: 1.55;
    margin-bottom: 0.6rem;
}

/* ── HR divider ── */
hr.dark-divider {
    border: none;
    border-top: 1px solid #2d3348;
    margin: 1rem 0;
}

/* ── Plotly chart container ── */
.js-plotly-plot .plotly .modebar {
    background: transparent !important;
}
.js-plotly-plot .plotly .modebar-btn path {
    fill: #8b92a8 !important;
}

/* ── Table styling ── */
[data-testid="stDataFrame"] table,
.dataframe {
    background: #1a1f2e !important;
    color: #e8eaf0 !important;
    border: 1px solid #2d3348 !important;
}
[data-testid="stDataFrame"] th, .dataframe th {
    background: #242938 !important;
    color: #8b92a8 !important;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    border-bottom: 1px solid #2d3348 !important;
}
[data-testid="stDataFrame"] td, .dataframe td {
    border-bottom: 1px solid #1e2335 !important;
    font-size: 0.86rem;
}

/* ── Info / warning / error boxes ── */
[data-testid="stInfo"] {
    background: rgba(79, 142, 247, 0.1) !important;
    border-left: 4px solid #4f8ef7 !important;
    color: #e8eaf0 !important;
}
[data-testid="stWarning"] {
    background: rgba(245, 158, 11, 0.1) !important;
    border-left: 4px solid #f59e0b !important;
    color: #e8eaf0 !important;
}
[data-testid="stError"] {
    background: rgba(239, 68, 68, 0.1) !important;
    border-left: 4px solid #ef4444 !important;
    color: #e8eaf0 !important;
}
[data-testid="stSuccess"] {
    background: rgba(34, 197, 94, 0.1) !important;
    border-left: 4px solid #22c55e !important;
    color: #e8eaf0 !important;
}

/* ── Select / multiselect / input dark overrides ── */
[data-testid="stSelectbox"] > div > div,
[data-testid="stMultiSelect"] > div > div {
    background: #1a1f2e !important;
    border-color: #2d3348 !important;
    color: #e8eaf0 !important;
}
.stTextInput > div > div > input,
.stTextArea textarea {
    background: #1a1f2e !important;
    border-color: #2d3348 !important;
    color: #e8eaf0 !important;
}

/* ── Expander ── */
details {
    background: #1a1f2e;
    border: 1px solid #2d3348;
    border-radius: 8px;
}
summary { color: #e8eaf0; font-weight: 600; }

/* ── Metric widget ── */
[data-testid="stMetric"] {
    background: #1a1f2e;
    border: 1px solid #2d3348;
    border-radius: 10px;
    padding: 0.8rem 1rem;
}
[data-testid="stMetricLabel"] { color: #8b92a8 !important; font-size: 0.78rem !important; }
[data-testid="stMetricValue"] { color: #e8eaf0 !important; }
[data-testid="stMetricDelta"] { font-size: 0.8rem !important; }

/* ── Button ── */
.stDownloadButton > button, .stButton > button {
    background: #1a1f2e !important;
    border: 1px solid #4f8ef7 !important;
    color: #4f8ef7 !important;
    border-radius: 6px;
    font-size: 0.84rem;
    transition: background 0.2s;
}
.stDownloadButton > button:hover, .stButton > button:hover {
    background: #4f8ef7 !important;
    color: #fff !important;
}

/* ── Tabs ── */
[data-testid="stTabs"] [role="tab"] {
    color: #8b92a8;
    border-bottom: 2px solid transparent;
}
[data-testid="stTabs"] [role="tab"][aria-selected="true"] {
    color: #4f8ef7;
    border-bottom: 2px solid #4f8ef7;
}

/* ── Code block ── */
pre { background: #1a1f2e !important; border: 1px solid #2d3348 !important; border-radius: 6px; }
code { color: #4f8ef7 !important; }

/* ── Footer ── */
.dash-footer {
    margin-top: 3rem;
    padding-top: 1rem;
    border-top: 1px solid #2d3348;
    text-align: center;
    color: #8b92a8;
    font-size: 0.75rem;
}
</style>
"""


def inject_css():
    """Inject the global dark-theme CSS (call once at top of each page)."""
    st.markdown(PAGE_CSS, unsafe_allow_html=True)


def page_header(icon: str, title: str, subtitle: str):
    """Render the page title + subtitle block."""
    st.markdown(
        f"""<div class="page-title">{icon}&nbsp;{title}</div>
            <div class="page-subtitle">{subtitle}</div>""",
        unsafe_allow_html=True,
    )


def section(label: str):
    """Render a section divider with accent left border."""
    st.markdown(f'<div class="section-header">{label}</div>', unsafe_allow_html=True)


def kpi_row(metrics: list):
    """
    Render a row of KPI cards.
    metrics: list of (label, value, sub_label) tuples.
    """
    cols = st.columns(len(metrics))
    for col, (label, value, sub) in zip(cols, metrics):
        col.markdown(
            f"""<div class="kpi-card">
                  <div class="kpi-label">{label}</div>
                  <div class="kpi-value">{value}</div>
                  <div class="kpi-sub">{sub}</div>
                </div>""",
            unsafe_allow_html=True,
        )


def divider():
    """Subtle dark horizontal rule."""
    st.markdown("<hr class='dark-divider'>", unsafe_allow_html=True)


def insight_card(text: str, icon: str = "💡"):
    """Green-bordered insight box."""
    st.markdown(
        f'<div class="insight-card">{icon}&nbsp; {text}</div>',
        unsafe_allow_html=True,
    )


def metric_delta(label: str, value, delta=None, delta_label: str = ""):
    """Wrapper around st.metric with optional delta."""
    st.metric(label=label, value=value, delta=delta, help=delta_label or None)


def filter_bar(*args):
    """
    Renders a horizontal filter row.
    Pass column-label strings; returns st.columns of that count.
    Usage: cols = filter_bar("Location", "Experience", "Role")
    """
    if args:
        cols = st.columns(len(args))
        for col, label in zip(cols, args):
            col.markdown(
                f"<span style='font-size:0.75rem;color:#8b92a8;text-transform:uppercase;"
                f"letter-spacing:0.05em;'>{label}</span>",
                unsafe_allow_html=True,
            )
        return cols
    return st.columns(1)


# ── Plotly theme ───────────────────────────────────────────────────────────

def apply_chart_style(fig: go.Figure, height: int = 400) -> go.Figure:
    """Apply the dark theme layout to any Plotly figure."""
    fig.update_layout(
        height=height,
        paper_bgcolor=SURFACE,
        plot_bgcolor=SURFACE,
        font=dict(
            family='"Inter",-apple-system,"Segoe UI",system-ui,sans-serif',
            size=12,
            color=TEXT,
        ),
        margin=dict(l=10, r=10, t=44, b=10),
        title_font=dict(size=13, color=TEXT),
        legend=dict(
            bgcolor="#242938",
            bordercolor=BORDER,
            borderwidth=1,
            font=dict(size=11, color=TEXT),
        ),
        xaxis=dict(
            gridcolor=BORDER,
            linecolor=BORDER,
            tickfont=dict(size=11, color=MUTED),
            title_font=dict(size=11, color=MUTED),
            zerolinecolor=BORDER,
        ),
        yaxis=dict(
            gridcolor=BORDER,
            linecolor=BORDER,
            tickfont=dict(size=11, color=MUTED),
            title_font=dict(size=11, color=MUTED),
            zerolinecolor=BORDER,
        ),
    )
    return fig


def hbar(data, x_col: str, y_col: str, title: str, color: str = PRIMARY,
         height: int = 400, x_label: str = "", y_label: str = "") -> go.Figure:
    """Horizontal bar chart — x_col is numeric axis, y_col is category axis."""
    fig = px.bar(
        data.sort_values(x_col),
        x=x_col,
        y=y_col,
        orientation="h",
        title=title,
        color_discrete_sequence=[color],
        labels={x_col: x_label or x_col, y_col: y_label or y_col},
    )
    fig.update_traces(
        marker_line_width=0,
        hovertemplate=f"<b>%{{y}}</b><br>{x_label or x_col}: %{{x:,}}<extra></extra>",
    )
    return apply_chart_style(fig, height)


def vbar(data, x_col: str, y_col: str, title: str, color: str = PRIMARY,
         height: int = 380, x_label: str = "", y_label: str = "") -> go.Figure:
    """Vertical bar chart."""
    fig = px.bar(
        data,
        x=x_col,
        y=y_col,
        title=title,
        color_discrete_sequence=[color],
        labels={x_col: x_label or x_col, y_col: y_label or y_col},
    )
    fig.update_traces(marker_line_width=0)
    return apply_chart_style(fig, height)


def box_plot(data, x_col: str, y_col: str, title: str, height: int = 450) -> go.Figure:
    """Box plot with dark theme."""
    fig = px.box(
        data,
        x=x_col,
        y=y_col,
        title=title,
        color=x_col,
        color_discrete_sequence=QUAL_COLORS,
        labels={x_col: x_col, y_col: "Salary (LPA)"},
        points=False,
    )
    fig.update_layout(showlegend=False)
    return apply_chart_style(fig, height)


def download_csv_button(df, label: str = "Download Filtered Data as CSV", key: str = "dl"):
    """Styled CSV download button."""
    st.download_button(
        label=f"⬇️  {label}",
        data=df.to_csv(index=False).encode("utf-8"),
        file_name="filtered_jobs.csv",
        mime="text/csv",
        key=key,
    )

