═══════════════════════════════════════════════════════ */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

html, body, [class*="css"] {
    font-family: "Inter", -apple-system, "Segoe UI", system-ui, sans-serif !important;
    background-color: #0f1117;
    color: #e8eaf0;
