"""
ui_helpers.py — Shared Streamlit UI components for the dark-theme dashboard.
No Streamlit cache decorators here — those live in app.py and pages/.
"""

import streamlit as st
import plotly.graph_objects as go
import plotly.express as px

# ── Palette ────────────────────────────────────────────────────────────────
PRIMARY        = "#4f8ef7"   # accent blue
SECONDARY      = "#7c5cd8"   # purple
ACCENT         = "#4f8ef7"   # alias for compat
ACCENT_GREEN   = "#22c55e"
ACCENT_AMBER   = "#f59e0b"
ACCENT_RED     = "#ef4444"
MUTED          = "#8b92a8"
TEXT           = "#e8eaf0"
BG             = "#0f1117"
SURFACE        = "#1a1f2e"
SURFACE2       = "#242938"
BORDER         = "#2d3348"

QUAL_COLORS = [
    "#4f8ef7", "#22c55e", "#f59e0b", "#ef4444",
    "#7c5cd8", "#06b6d4", "#ec4899", "#10b981",
    "#f97316", "#8b5cf6",
]

# ── IJMI SVG Logo ─────────────────────────────────────────────────────────
# Original minimal mark: a stylised bar-chart rising inside a rounded square.
LOGO_SVG = """
<svg xmlns="http://www.w3.org/2000/svg" width="40" height="40" viewBox="0 0 40 40">
  <rect width="40" height="40" rx="9" fill="#1a1f2e"/>
  <rect x="8"  y="24" width="5" height="9"  rx="1.5" fill="#4f8ef7"/>
  <rect x="16" y="17" width="5" height="16" rx="1.5" fill="#4f8ef7" opacity="0.8"/>
  <rect x="24" y="10" width="5" height="23" rx="1.5" fill="#4f8ef7" opacity="0.6"/>
  <path d="M9 24 L18 17 L26 10" stroke="#22c55e" stroke-width="1.8"
        stroke-linecap="round" stroke-linejoin="round" fill="none"/>
  <circle cx="26" cy="10" r="2" fill="#22c55e"/>
</svg>
"""

LOGO_SVG_LARGE = """
<svg xmlns="http://www.w3.org/2000/svg" width="52" height="52" viewBox="0 0 40 40">
